contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: pool (must be a curated pool per C's onlyPool), member to receive synthetic, amount to mint, and a flag whether to call as that pool
    function run(address pool, address member, uint256 amount) public payable {
        require(pool != address(0) && member != address(0), true);

        // read before values via public getters
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeDebt = c.getmapAddress_LPDebt(pool);
        uint256 beforeBalanceMember = c.balanceOf(member);

        // We must call mintSynth as if msg.sender == pool. The checker deploys c and then this contract is the msg.sender for calls.
        // To simulate the pool calling, we invoke the external call by using the pool contract address as the caller is not possible here.
        // However C restricts mintSynth with onlyPool which checks iPOOLFACTORY(_DAO().POOLFACTORY()).isCuratedPool(msg.sender).
        // The only way within constraints is to attempt the call and capture whether it reverts; the property will relate the non-revert case.

        bool reverted;
        try c.mintSynth(member, amount) {
            // If this contract is recognized as a curated pool, call succeeded
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after values
        uint256 afterTotal = c.totalSupply();
        uint256 afterDebt = c.getmapAddress_LPDebt(pool);
        uint256 afterBalanceMember = c.balanceOf(member);

        // General rule: if the call did NOT revert then
        // 1) totalSupply increased by exactly amount
        // 2) mapSynth_LPDebt for the pool increased by exactly amount
        // 3) member's balance increased by exactly amount
        // If the call reverted then none of those increases happened (we cannot observe intermediate state), so we require that at least one of the before/after shows no increase for each field.

        assert(
            // either call reverted and no increases observed
            (reverted && (afterTotal == beforeTotal) && (afterDebt == beforeDebt) && (afterBalanceMember == beforeBalanceMember))
            ||
            // or call succeeded and the three increases equal amount
            (!reverted && (afterTotal == beforeTotal + amount) && (afterDebt == beforeDebt + amount) && (afterBalanceMember == beforeBalanceMember + amount))
        );
    }

    receive() external payable {}
}

