contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry: caller provides a pool address (must be a curated pool in DAO),
    // the member to receive minted synth, and an amount indicating desired synth to mint.
    // We cannot enforce the pool is curated here; the property will account for possible revert.
    function run(address pool, address member, uint256 amount) public payable {
        require(member != address(0), "member0");

        // read before-values
        uint beforeBalance_member = c.balanceOf(member);
        uint beforeDebt_pool = c.getmapAddress_LPDebt(pool);
        uint beforeLP_balance_pool = c.getmapAddress_LPBalance(pool);

        // attempt to simulate a call from the pool: our test contract is the msg.sender for calls on c.
        // The property should allow for the call reverting if pool is not a curated pool.
        bool reverted;
        try c.mintSynth(member, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint afterBalance_member = c.balanceOf(member);
        uint afterDebt_pool = c.getmapAddress_LPDebt(pool);
        uint afterLP_balance_pool = c.getmapAddress_LPBalance(pool);

        // General property to hold for all inputs:
        // If the call reverted, no observable state change must have occurred in c for the readable parts used here.
        // If the call succeeded, then: (1) member's balance increased by exactly 'amount',
        // (2) pool's recorded debt increased by exactly 'amount', and (3) pool's recorded LP balance did not decrease (it must be >= before).
        // We assert this disjunction as a single general rule.
        assert(
            (reverted && afterBalance_member == beforeBalance_member && afterDebt_pool == beforeDebt_pool && afterLP_balance_pool == beforeLP_balance_pool)
            ||
            (!reverted && afterBalance_member == beforeBalance_member + amount && afterDebt_pool == beforeDebt_pool + amount && afterLP_balance_pool >= beforeLP_balance_pool)
        );
    }

    receive() external payable {}
}

