        uint beforeTotal = c.totalSupply();
        uint beforeDebt = c.getmapAddress_LPDebt(pool);

        // Attempt to call c.mintSynth as if msg.sender == pool by using a low-level call from this contract is impossible.
        // Instead, we call mintSynth directly; it will revert unless msg.sender is a curated pool. We capture revert flag.
        bool reverted;
        try c.mintSynth(member, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterTotal = c.totalSupply();
        uint afterDebt = c.getmapAddress_LPDebt(pool);

        // General rule: if the call did not revert then totalSupply increased by exactly `amount` and the recorded debt for that pool increased by `amount`.
        // If it reverted, state must be unchanged w.r.t these observables (conservative): totalSupply and debt remain equal to before-values.
        assert( (!reverted && afterTotal == beforeTotal + amount && afterDebt == beforeDebt + amount) || (reverted && afterTotal == beforeTotal && afterDebt == beforeDebt) );
    }

    receive() external payable {}
 }

