contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call on behalf of a Pool (msg.sender for c.mintSynth will be this contract)
    // We require that the pool address passed is reported as curated by the DAO via the public functions of c's environment in the real system,
    // but here we cannot query DAO; instead we simply exercise mintSynth and assert the invariant about totalSupply and balance when the call succeeds.
    function run(address pool, address member, uint amount) public payable {
        require(member != address(0), "member0");
        // record before values
        uint beforeTotal = c.totalSupply();
        uint beforeBal = c.balanceOf(member);

        bool reverted;
        // call mintSynth on C with this contract as msg.sender from test: but mintSynth has onlyPool modifier which checks iPOOLFACTORY(...).isCuratedPool(msg.sender)
        // In many deployments msg.sender must be a curated pool; if not curated this will revert. We capture that.
        try c.mintSynth{ }(member, amount) returns (uint syntheticAmount) {
            reverted = false;
            // syntheticAmount is returned but we don't rely on it beyond reading public state
        } catch {
            reverted = true;
        }

        uint afterTotal = c.totalSupply();
        uint afterBal = c.balanceOf(member);

        // If the call reverted, then no state change is expected; if it succeeded, then totalSupply increased by 'amount' and member balance increased by 'amount'.
        // Express: reverted || (afterTotal == beforeTotal + amount && afterBal == beforeBal + amount)
        assert(reverted || (afterTotal == beforeTotal + amount && afterBal == beforeBal + amount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to call mintSynth as this contract (msg.sender for C will be this contract).
    // If it reverts (not a curated pool) then no state change should occur. If it succeeds,
    // totalSupply and member balance must increase by exactly `amount`.
    function run(address member, uint256 amount) public payable {
        require(member != address(0), "member0");

        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(member);

        bool reverted = false;
        // Call mintSynth and capture revert by using low-level call
        bytes memory payload = abi.encodeWithSelector(c.mintSynth.selector, member, amount);
        (bool ok, ) = address(c).call(payload);
        if (!ok) {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(member);

        // If reverted: no change to totalSupply or balance. If succeeded: both increased by exactly amount.
        assert(
            reverted ? (afterTotal == beforeTotal && afterBal == beforeBal) : (afterTotal == beforeTotal + amount && afterBal == beforeBal + amount)
        );
    }

    receive() external payable {}
}

