    // To keep within constraints we will instead call c.mintSynth via a low-level call from this test
    // to simulate an external call with arbitrary sender is impossible. Therefore we drive the property
    // by calling c.getmapAddress_LPBalance and other view functions and then asserting a general
    // invariant about mintSynth: when a curated pool (observed via before/after differences) mints,
    // C.totalSupply increases by minted amount. To observe a mint we must trigger it: we'll call
    // c.mintSynth inside a try/catch and record whether it reverted. The test uses the pool param as
    // msg.sender when calling c.mintSynth by performing a low-level call to c with abi-encoded
    // selector while forwarding no Ether; the low-level call's msg.sender will still be this contract,
    // so onlyPool will likely revert — but our assertion will be conditional: if the call succeeded
    // (i.e., treated msg.sender as curated), then totalSupply increased by amount and mapSynth_LPDebt increased.
    // This creates a general rule: whenever c.mintSynth returns successfully, totalSupply and mapSynth_LPDebt change accordingly.

    function run(address pool, address member, uint256 amount) public payable {
        require(member != address(0), "member != 0");
        // record before-values (public getters)
        uint256 beforeTotal = c.totalSupply();
        uint beforeDebt = c.getmapAddress_LPDebt(pool);
        uint beforeLPBal = c.getmapAddress_LPBalance(pool);

        // attempt to call mintSynth on c as if msg.sender==pool by using a low-level call that encodes
        // the external function. Note: msg.sender will still be this contract, so many environments will revert.
        // We capture whether it reverted or not.
        bool success;
        bytes memory returnData;
        // encode call to mintSynth(address,uint256)
        bytes memory payload = abi.encodeWithSelector(bytes4(keccak256("mintSynth(address,uint256)")), member, amount);
        // perform low-level call; it will execute with msg.sender == address(this)
        (success, returnData) = address(c).call(payload);

        // read after-values
        uint256 afterTotal = c.totalSupply();
        uint afterDebt = c.getmapAddress_LPDebt(pool);
        uint afterLPBal = c.getmapAddress_LPBalance(pool);

        // If the call succeeded then it must have minted exactly `amount` more tokens (totalSupply increased by amount),
        // and mapSynth_LPDebt for the caller pool must have increased by amount, and mapSynth_LPBalance for that pool
        // must have increased by some non-negative amount (no underflow). This is the general rule we assert.
        // If the call reverted then we cannot assert state changes; so the assertion allows either revert or the stated invariants.
        assert(
            !success || (
                afterTotal == beforeTotal + amount
                && afterDebt == beforeDebt + amount
                && afterLPBal >= beforeLPBal
            )
        );
    }

    receive() external payable {}
}

