contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry exercising mintSynth from a Pool (msg.sender will be the Pool as required by onlyPool)
    // We simulate a Pool by calling mintSynth directly from this contract, but the contract-level onlyPool in C
    // requires msg.sender to be a curated pool; since the checker deploys a fresh C and cannot mark this
    // contract as curated, we conservatively place no precondition and capture revert behavior.
    function run(address pool, address member, uint amount) public payable {
        require(pool != address(0) && member != address(0));

        // read before-values through public getters
        uint beforeTotal = c.totalSupply();
        uint beforeMember = c.balanceOf(member);
        uint beforeLPDebt = c.getmapAddress_LPDebt(pool);
        uint beforeLPBal = c.getmapAddress_LPBalance(pool);

        bool reverted;
        // call mintSynth: it may revert if caller is not a curated pool; capture that
        try c.mintSynth(member, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint afterTotal = c.totalSupply();
        uint afterMember = c.balanceOf(member);
        uint afterLPDebt = c.getmapAddress_LPDebt(pool);
        uint afterLPBal = c.getmapAddress_LPBalance(pool);

        // General property:
        // If the call did not revert, then totalSupply and member balance increased by exactly `amount`,
        // and the pool's LP debt increased by amount, and its LP balance is >= before (non-decreasing).
        // If the call reverted, none of these observable values should have increased (they remain equal to before).
        assert(
            (!reverted && afterTotal == beforeTotal + amount && afterMember == beforeMember + amount && afterLPDebt == beforeLPDebt + amount && afterLPBal >= beforeLPBal)
            || (reverted && afterTotal == beforeTotal && afterMember == beforeMember && afterLPDebt == beforeLPDebt && afterLPBal == beforeLPBal)
        );
    }

    receive() external payable {}
}

